    static func text(_ key: String, language: AppLanguage = L10n.shared.language) -> String {
        guard let values = table[key], let index = languages.firstIndex(of: language),
              values.indices.contains(index) else { return key }
        return values[index]
    }

    static func isComplete(for language: AppLanguage) -> Bool {
        guard let index = languages.firstIndex(of: language) else { return false }
        return table.values.allSatisfy { $0.count == languages.count && !$0[index].isEmpty }
    }
}
